import { fireEvent, render, screen, waitFor } from "@testing-library/react";
import { QueryClient, QueryClientProvider } from "react-query";
import { MemoryRouter, Route, Routes } from "react-router-dom";

import { ShareResultsPage } from "./ShareResultsPage";
import { getShareResultsEvent, getShareResultsView } from "./api/v3/share";
import { getFencersByIdsInBatches } from "./api/v3/view/fencer";
import { getFencerStandings } from "./api/v3/view/standings";
import { HttpError } from "./api/http";

jest.mock("./api/v3/share", () => ({
  getShareResultsView: jest.fn(),
  getShareResultsEvent: jest.fn(),
}));

jest.mock("./api/v3/view/standings", () => ({
  getFencerStandings: jest.fn(),
}));

jest.mock("./api/v3/view/fencer", () => ({
  getFencersByIdsInBatches: jest.fn(),
}));

const getShareResultsViewMock = getShareResultsView as jest.MockedFunction<
  typeof getShareResultsView
>;
const getShareResultsEventMock = getShareResultsEvent as jest.MockedFunction<
  typeof getShareResultsEvent
>;
const getFencersByIdsInBatchesMock = getFencersByIdsInBatches as jest.MockedFunction<
  typeof getFencersByIdsInBatches
>;
const getFencerStandingsMock = getFencerStandings as jest.MockedFunction<typeof getFencerStandings>;

const VIEW = {
  fencerId: "f.u.123",
  fencerName: "DOE Jane",
  createdAt: "2026-01-01T00:00:00Z",
  expiresAt: "2026-04-01T00:00:00Z",
  tournaments: [
    {
      id: "t.1",
      name: "Example Open",
      when: "2026-03-01",
      location: "Austin",
      eventIds: ["e.1"],
    },
  ],
};

const EVENT = {
  name: "Y14 Women's Foil",
  results: [
    {
      id: "m.1",
      opponent: { id: "f.u.999", name: "SMITH Alex" },
      stage: { pool: { sequence: 1 } },
      myTouches: 5,
      opponentTouches: 2,
      resultClass: "majorWin" as const,
      videos: [
        {
          id: "v.1",
          url: "https://youtu.be/abc",
          visibility: "familyGroup" as const,
        },
      ],
    },
  ],
};

function renderShare(path: string) {
  const client = new QueryClient({
    defaultOptions: { queries: { retry: false } },
  });
  return render(
    <QueryClientProvider client={client}>
      <MemoryRouter initialEntries={[path]}>
        <Routes>
          <Route path="/r/:token" element={<ShareResultsPage />} />
        </Routes>
      </MemoryRouter>
    </QueryClientProvider>,
  );
}

describe("ShareResultsPage", () => {
  beforeEach(() => {
    getShareResultsViewMock.mockReset();
    getShareResultsEventMock.mockReset();
    getFencersByIdsInBatchesMock.mockReset();
    getFencerStandingsMock.mockReset();
    getFencersByIdsInBatchesMock.mockImplementation(async (_ids, { onBatch } = {}) => {
      const hydratedOpponent = {
        id: "f.u.999",
        name: "SMITH Alex",
        rating: null,
        club: null,
        firstCompetitionYear: 2020,
        birthYear: 2010,
        country: null,
        gender: null,
        strength: null,
      };
      onBatch?.([hydratedOpponent]);
      return [hydratedOpponent];
    });
    getFencerStandingsMock.mockResolvedValue({
      fencerId: "f.u.123",
      identityResolved: true,
      standings: [],
    });
    document.head.querySelectorAll("meta[data-flunge-share-policy]").forEach((el) => el.remove());
  });

  afterEach(() => {
    document.head.querySelectorAll("meta[data-flunge-share-policy]").forEach((el) => el.remove());
  });

  it("shows a generic unavailable state when the view API fails", async () => {
    getShareResultsViewMock.mockRejectedValue(new Error("Failed to GET"));

    renderShare("/r/unknownToken");

    expect(await screen.findByText("This link isn't available.")).toBeTruthy();
    expect(screen.queryByText(/sign up/i)).toBeNull();
    expect(screen.queryByText(/create an account/i)).toBeNull();
    expect(screen.queryByText(/revoked/i)).toBeNull();
    expect(screen.queryByText(/expired/i)).toBeNull();
  });

  it("renders the fencer name, opponent as text, and noreferrer video anchors", async () => {
    getShareResultsViewMock.mockResolvedValue(VIEW);
    getShareResultsEventMock.mockResolvedValue(EVENT);

    renderShare("/r/aK9mQx2LpN4rT8wB");

    expect(await screen.findByText("DOE Jane")).toBeTruthy();
    expect(screen.queryByText(/sign up/i)).toBeNull();
    expect(screen.queryByText(/refresh results/i)).toBeNull();
    expect(screen.queryByText(/select a connected fencer/i)).toBeNull();

    expect(document.head.querySelector('meta[name="robots"]')?.getAttribute("content")).toBe(
      "noindex, nofollow",
    );
    expect(document.head.querySelector('meta[name="referrer"]')?.getAttribute("content")).toBe(
      "no-referrer",
    );

    fireEvent.click(screen.getByText("Example Open"));

    expect(await screen.findByText("SMITH Alex")).toBeTruthy();
    expect(screen.getByText("SMITH Alex").closest("a")).toBeNull();
    expect(await screen.findByText("2010")).toBeTruthy();
    expect(screen.getByRole("img", { name: /competing/ })).toBeTruthy();
    expect(screen.getByText("Y14 Women's Foil")).toBeTruthy();

    const video = screen.getByRole("link", { name: "Watch bout video" });
    expect(video.getAttribute("rel")).toBe("noopener noreferrer");
    expect(video.getAttribute("target")).toBe("_blank");
    expect(video.getAttribute("href")).toBe("https://youtu.be/abc");
    expect(video.getAttribute("referrerPolicy") ?? video.getAttribute("referrerpolicy")).toBe(
      "no-referrer",
    );

    expect(getShareResultsViewMock).toHaveBeenCalledWith("aK9mQx2LpN4rT8wB");
    expect(getShareResultsEventMock).toHaveBeenCalledWith("aK9mQx2LpN4rT8wB", "t.1", "e.1");
    expect(getFencerStandingsMock).toHaveBeenCalledWith("f.u.123");
  });

  it("does not send the share token on the public standings callout", async () => {
    getShareResultsViewMock.mockResolvedValue({ ...VIEW, tournaments: [] });

    renderShare("/r/aK9mQx2LpN4rT8wB");

    await waitFor(() => {
      expect(getFencerStandingsMock).toHaveBeenCalledWith("f.u.123");
    });
    expect(getFencerStandingsMock.mock.calls[0]?.length).toBe(1);
  });

  it("shows an empty-results state when the view has no tournaments", async () => {
    getShareResultsViewMock.mockResolvedValue({ ...VIEW, tournaments: [] });

    renderShare("/r/aK9mQx2LpN4rT8wB");

    expect(await screen.findByText("No results to show.")).toBeTruthy();
  });

  it("keeps the page live when an event request fails", async () => {
    getShareResultsViewMock.mockResolvedValue(VIEW);
    getShareResultsEventMock.mockRejectedValue(new Error("Failed to GET"));

    renderShare("/r/aK9mQx2LpN4rT8wB");

    expect(await screen.findByText("DOE Jane")).toBeTruthy();
    fireEvent.click(screen.getByText("Example Open"));

    expect(await screen.findByText("Unable to load this event.")).toBeTruthy();
    expect(screen.queryByText("This link isn't available.")).toBeNull();
  });

  it("shows the unavailable state when an event request returns 404", async () => {
    getShareResultsViewMock
      .mockResolvedValueOnce(VIEW)
      .mockRejectedValueOnce(new HttpError("Failed to GET", 404));
    getShareResultsEventMock.mockRejectedValue(new HttpError("Failed to GET", 404));

    renderShare("/r/aK9mQx2LpN4rT8wB");

    expect(await screen.findByText("DOE Jane")).toBeTruthy();
    fireEvent.click(screen.getByText("Example Open"));

    expect(await screen.findByText("This link isn't available.")).toBeTruthy();
    expect(screen.queryByText("DOE Jane")).toBeNull();
  });
});

