import * as React from "react";
import { useParams } from "react-router-dom";
import { useQuery, useQueryClient } from "react-query";
import AccordionGroup from "@mui/joy/AccordionGroup";
import { Link, Stack, Typography } from "@mui/joy";
import { LinkOff, YouTube } from "@mui/icons-material";

import { LoadingState, StateCard } from "./components/PageStates";
import { FencerStandingsCallout } from "./components/FencerStandingsCallout";
import {
  ResultsEventCard,
  ResultsMatchesTable,
  ResultsTournamentAccordion,
} from "./components/ResultsPresentation";
import { getResultVideos } from "./components/ResultVideos";
import { getShareResultsEvent, getShareResultsView } from "./api/v3/share";
import { HttpError } from "./api/http";
import type { V3MatchResult, V3Tournament } from "./api/v3/view/results";
import { applySharePageDocumentPolicy } from "./sharePageDocumentPolicy";
import { parseDate } from "./util";

const UNAVAILABLE_COPY = "This link isn't available.";

export function ShareResultsPage() {
  const { token } = useParams<{ token: string }>();

  React.useEffect(() => applySharePageDocumentPolicy(), []);

  const viewQuery = useQuery(["shareResultsView", token], () => getShareResultsView(token!), {
    enabled: !!token,
    retry: false,
  });

  React.useEffect(() => {
    if (!viewQuery.data?.fencerName) {
      return;
    }
    const previous = document.title;
    document.title = `${viewQuery.data.fencerName} — Flunge`;
    return () => {
      document.title = previous;
    };
  }, [viewQuery.data?.fencerName]);

  if (!token || viewQuery.isError) {
    return <UnavailableState />;
  }

  if (viewQuery.isLoading || !viewQuery.data) {
    return <LoadingState message="Loading results..." />;
  }

  const { fencerName, fencerId, tournaments } = viewQuery.data;
  const sorted = [...tournaments].sort(
    (a, b) => parseDate(b.when).getTime() - parseDate(a.when).getTime(),
  );

  return (
    <Stack spacing={1}>
      <Typography level="h3">{fencerName}</Typography>
      <FencerStandingsCallout fencerId={fencerId} />
      {sorted.length === 0 ? (
        <Typography level="body-sm" color="neutral">
          No results to show.
        </Typography>
      ) : (
        <AccordionGroup size="sm">
          {sorted.map((tournament) => (
            <ResultsTournamentAccordion key={tournament.id} tournament={tournament}>
              <ShareTournamentEvents token={token} tournament={tournament} />
            </ResultsTournamentAccordion>
          ))}
        </AccordionGroup>
      )}
    </Stack>
  );
}

function UnavailableState() {
  return (
    <Stack alignItems="center" justifyContent="center" sx={{ minHeight: "50vh", p: 2 }}>
      <StateCard icon={LinkOff} title={UNAVAILABLE_COPY} message="" />
    </Stack>
  );
}

function ShareTournamentEvents({ token, tournament }: { token: string; tournament: V3Tournament }) {
  return (
    <Stack spacing={2}>
      {tournament.eventIds.map((eventId) => (
        <ShareEventCard
          key={eventId}
          token={token}
          tournamentId={tournament.id}
          eventId={eventId}
        />
      ))}
    </Stack>
  );
}

function ShareEventCard({
  token,
  tournamentId,
  eventId,
}: {
  token: string;
  tournamentId: string;
  eventId: string;
}) {
  const queryClient = useQueryClient();
  const query = useQuery(
    ["shareResultsEvent", token, tournamentId, eventId],
    () => getShareResultsEvent(token, tournamentId, eventId),
    {
      retry: false,
      onError: (error) => {
        if (error instanceof HttpError && error.status === 404) {
          void queryClient.invalidateQueries(["shareResultsView", token]);
        }
      },
    },
  );

  const event = query.data;

  return (
    <ResultsEventCard
      event={event}
      errorMessage={query.isError ? "Unable to load this event." : undefined}
    >
      {(loadedEvent) => (
        <ResultsMatchesTable
          matches={loadedEvent.results}
          renderOpponentName={(opponent) => opponent.name}
          renderVideo={(_opponent, match) => <ShareVideoAnchors match={match} />}
        />
      )}
    </ResultsEventCard>
  );
}

function ShareVideoAnchors({ match }: { match: V3MatchResult }) {
  const videos = getResultVideos(match).filter((video) => video.url.trim().length > 0);
  if (videos.length === 0) {
    return null;
  }
  return (
    <Stack direction="row" spacing={1}>
      {videos.map((video, index) => (
        <Link
          key={video.id || `${match.id}-video-${index}`}
          href={video.url}
          target="_blank"
          rel="noopener noreferrer"
          referrerPolicy="no-referrer"
          level="body-lg"
          aria-label="Watch bout video"
        >
          <YouTube />
        </Link>
      ))}
    </Stack>
  );
}

